// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// The ticketing chat's privacy notice: plain text where the only markup is a
// markdown link [texte](https://…). Anything else, including a non-https link,
// stays literal text; nothing is ever parsed as HTML.
export type NoticeSegment = { kind: "text"; text: string } | { kind: "link"; label: string; href: string };

const LINK = /\[([^\]\n]+)\]\((https:\/\/[^\s)]+)\)/g;

export function parseNotice(text: string): NoticeSegment[] {
  const segments: NoticeSegment[] = [];
  let last = 0;
  for (const match of text.matchAll(LINK)) {
    const start = match.index ?? 0;
    if (start > last) segments.push({ kind: "text", text: text.slice(last, start) });
    segments.push({ kind: "link", label: match[1], href: match[2] });
    last = start + match[0].length;
  }
  if (last < text.length) segments.push({ kind: "text", text: text.slice(last) });
  return segments;
}

// The notice to show, or null: human mode only, and only a non-empty string
// (the Shop Assistant never sends one; a missing key reads like null).
export function privacyNoticeOf(config: { mode?: unknown; privacy_notice?: unknown }): string | null {
  if (config.mode !== "human" || typeof config.privacy_notice !== "string") return null;
  const notice = config.privacy_notice.trim();
  return notice ? notice : null;
}
